function feedPage(ctx) {
  const feedTabs = [["all", "Все новости"], ["mine", "Мои публикации"], ["subs", "Подписки"], ["saved", "Сохранённое"]];
  const posts = [
    { company: "АвтоПрофи", initials: "АП", title: "Запустили практический курс по PPF", text: "Пять дней работы с реальными автомобилями: подготовка, раскрой, установка на сложные элементы и контроль качества. Для мастеров с базовым опытом.", tag: "Обучение" },
    { company: "Shine&Go", initials: "SG", title: "Как подготовить студию к сезону", text: "Собрали чек-лист по запасам химии, микрофибры и расходников. Коллективная закупка помогает снизить стоимость почти на четверть.", tag: "Бизнес" },
    { company: "Учебный центр СОУС", initials: "СО", title: "Новые материалы по химчистке кожи", text: "Разобрали типы кожи, безопасную очистку и финишную защиту. Материал доступен в разделе теории.", tag: "Материалы" },
  ];
  const visiblePosts = posts.filter((post, index) => ctx.feedTab === "all" || (ctx.feedTab === "mine" && post.company === ROLES[ctx.role].name) || (ctx.feedTab === "subs" && index < 2) || (ctx.feedTab === "saved" && index === 1));
  return `${hero({ section: "Профессиональное сообщество", title: "Лента и Автоновости", lead: "Новости компаний, опыт мастеров, обучающие материалы и объявления индустрии.", image: "12", actions: btn("Опубликовать пост", { modal: "post.create", iconName: "plus", cls: "primary" }), stats: [[128, "публикаций"], [34, "компании"], [12, "новых за неделю", true]] })}<div class="wrap feed-grid"><aside class="feed-nav"><div class="card"><div class="post-head">${avatar(ROLES[ctx.role].initials)}<div><b>${ROLES[ctx.role].name}</b><div class="hint">${ROLES[ctx.role].label}</div></div></div><div class="divider"></div><nav class="dash-nav">${feedTabs.map(([key, label]) => `<button class="${ctx.feedTab === key ? "active" : ""}" data-action="feed-tab" data-tab="${key}">${label}</button>`).join("")}</nav></div></aside><div class="stack"><section class="card composer"><div class="row"><input class="input grow" aria-label="Текст публикации" placeholder="Поделитесь опытом или новостью компании…" data-action="open-post-input">${btn("Опубликовать", { modal: "post.create", cls: "primary", iconName: "plus" })}</div><div class="row"><button class="linkbtn" data-modal="work.create">${icon("image", "sm")} Примеры работ</button><button class="linkbtn" data-modal="post.create">${icon("file", "sm")} Материал</button></div></section>${visiblePosts.length ? visiblePosts.map((post, i) => `<article class="card"><div class="post-head">${avatar(post.initials)}<div class="grow"><b>${post.company}</b><div class="hint">${i + 1} ч назад · ${post.tag}</div></div>${btn("", { action: "post-menu", iconName: "more", cls: "sm icon-only ghost", attrs: 'aria-label="Действия с публикацией"' })}</div><h2 class="mt-2">${post.title}</h2><p class="muted small">${post.text}</p><div class="gallery"><button data-modal="gallery.view" style="--hero-art:url('/public/images/heroes/0${i + 2}-dark.webp')" aria-label="Открыть фото"></button><button data-modal="gallery.view" style="--hero-art:url('/public/images/heroes/0${i + 3}-dark.webp')" aria-label="Открыть фото"></button><button data-modal="gallery.view" style="--hero-art:url('/public/images/heroes/0${i + 4}-dark.webp')" aria-label="Открыть фото"></button></div><div class="post-actions"><button data-action="like">${icon("heart", "sm")} ${12 + i * 7}</button><button data-action="comment">${icon("message", "sm")} ${3 + i}</button><button data-action="favorite">${icon("bookmark", "sm")} Сохранить</button><button data-action="share">${icon("share", "sm")}</button></div></article>`).join("") : emptyState("Пока нет публикаций", "В этой вкладке пока нет постов. Создайте первую публикацию или выберите другой раздел.", "open-post-input", "Создать публикацию")}</div></div>${footer()}`;
}

