function detailCatalogPage(ctx, type, id) {
  const source = { vacancies: VACANCIES, specialists: SPECIALISTS, gigs: GIGS, orders: ORDERS, suppliers: SUPPLIERS, companies: COMPANIES, promos: PROMOS }[type];
  const item = source.find((entry) => entry.id === id) || source[0];
  const config = DETAIL_CONTENT[type];
  const statValues = type === "specialists" ? ["6 лет", "9,6 / 10", "38"] : type === "companies" || type === "suppliers" ? ["9,8 / 10", "12", "3"] : [item.salary, item.schedule, item.experience];
  const content = config.blocks.map((title, index) => sectionCard(title, index === 0 ? `<div class="prose"><p>${item.description}</p><p>Работаем по понятному регламенту и заранее согласовываем результат, сроки и стоимость. Все детали можно обсудить перед началом.</p></div>` : index === 1 ? `<div class="grid2"><div class="callout"><b>Профессиональный подход</b><p class="small mb-0">Опыт работы с профильными материалами и оборудованием.</p></div><div class="callout"><b>Понятные условия</b><p class="small mb-0">Фиксируем объём работ, цену и сроки до подтверждения.</p></div></div><ul class="prose"><li>Соблюдение стандартов качества и безопасности.</li><li>Фото и подтверждение результата.</li><li>Связь через платформу на каждом этапе.</li></ul>` : `<div class="map" style="min-height:260px;height:280px"><button class="map-pin" style="left:48%;top:42%" data-modal="map.city" aria-label="Открыть карту">${icon("pin")}</button></div><p class="hint mt-1">${item.city} · Точный адрес доступен после подтверждения.</p>`, { number: `0${index + 1}` }));
  const rail = `${sectionCard(config.railTitle, `<div class="post-head">${avatar(item.company.split(" ").map((p) => p[0]).join("").slice(0, 2), "lg")}<div><b>${item.company}</b><div class="hint">${item.city}</div></div></div><div class="divider"></div><div class="info-list">${infoItem("shield", "Статус", "Документы проверены")}${infoItem("star", "Рейтинг", "9,8 / 10")}${infoItem("pin", "Локация", item.city)}</div><div class="stack mt-2">${btn(config.applyLabel, { modal: config.apply, cls: "primary block", iconName: type === "specialists" ? "send" : "check" })}${btn("Написать сообщение", { modal: "message.new", cls: "secondary block", iconName: "message" })}</div>`)}${type === "promos" && item.id === "promo-001" ? sectionCard("Растущий кешбэк", `<p class="small muted">Сумма растёт с каждой активацией. Присоединяйтесь к программе и отправляйте чеки после услуги.</p>${btn("Участвовать в кешбэке", { path: "/promos/cashback/promo-001", cls: "primary block" })}`) : ""}${type === "vacancies" ? sectionCard("Сохранить и поделиться", `<div class="row">${btn("В избранное", { action: "favorite", iconName: "heart", cls: "secondary grow" })}${btn("", { action: "share", iconName: "share", cls: "secondary icon-only", attrs: 'aria-label="Поделиться"' })}</div>`) : sectionCard("Безопасность", `<p class="small muted">Не переводите деньги вне платформы до подтверждения условий. Если что-то выглядит подозрительно, отправьте жалобу.</p>${btn("Пожаловаться", { modal: "report.create", cls: "ghost block", iconName: "flag" })}`)}`;
  return detailPage({ back: config.back, backPath: `/${type}`, section: config.section, title: item.title, subtitle: `${item.company} · ${item.city} · ${item.schedule}`, stats: statValues.map((value, i) => [value, config.labels[i], i === 0]), badges: item.tags, actions: `${btn(config.applyLabel, { modal: config.apply, cls: "primary lg", iconName: "check" })}${btn("Сохранить", { action: "favorite", cls: "secondary lg", iconName: "heart" })}`, content: content.join(""), rail });
}

