  if (active === "payments") return `${sectionCard("Тариф и подписка", `<div class="row between"><div><b>Профессиональный</b><p class="small muted mb-0">Все функции платформы, приоритетные размещения и аналитика.</p></div>${badge("Активна до 15.12.2026", "ok")}</div><div class="row mt-2">${btn("Сравнить тарифы", { modal: "tariff.compare", cls: "primary" })}${btn("История платежей", { path: "/dashboard/billing/history", cls: "secondary" })}</div>`)}${sectionCard("Последние платежи", table(["Дата", "Сумма", "Период", "Статус"], [["15.11.2026", "2 990 ₽", "1 месяц", badge("Оплачено", "ok")], ["15.10.2026", "2 990 ₽", "1 месяц", badge("Оплачено", "ok")]]))}`;
  if (active === "privacy") return sectionCard("Приватность и безопасность", `<div class="stack">${[["Показывать онлайн-статус", true], ["Разрешить сообщения от контактов", true], ["Показывать телефон после подтверждения", false], ["Браузерные push-уведомления", true]].map(([label, checked]) => `<label class="row between card flat"><span>${label}</span><input class="sw" type="checkbox" ${checked ? "checked" : ""}></label>`).join("")}<div class="callout danger"><b>Удаление аккаунта</b><p class="small">Данные будут скрыты, а удаление станет необратимым через 30 дней.</p>${btn("Удалить аккаунт", { modal: "confirm.delete", cls: "danger sm" })}</div></div>`);
